type AlertKind = keyof typeof ICONS; // "note" | "tip" | "important" | "warning" | "caution"
function badge(kind: AlertKind) {
  const el = document.createElement("span");
  el.className = "gh-alert-badge";
  el.contentEditable = "false";
  const icon = ICONS[kind];
  if (!icon) return el;
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 24 24");
  // set fill/stroke attributes ...
  svg.innerHTML = icon; // icon is static trusted constant
  const label = document.createElement("span");
  label.textContent = kind.charAt(0).toUpperCase() + kind.slice(1);
  el.append(svg, label);
  return el;
}

